-- Seed data: LLM Specification — Gotcha vs Contraction
-- Updated with 35+ regions from 115 search log entries

INSERT INTO investigations (id, title, summary, tags) VALUES
  ('INV.LLM.SPEC.CONTRACT', 'Gotcha vs Contraction — LLM Specification Pattern',
   'Cross-region investigation into two complementary strategies for constraining LLM output: contraction (positive constraints, schemas, scope narrowing) and gotcha (negative constraints, hard stops, antipattern enumeration). Mechanistic, empirical, and practice-based evidence from 35+ regions worldwide.',
   'llm,prompt-engineering,constraint,specification,reward-hacking,negation');

INSERT INTO fundamentals (id, investigation_id, title, principle, mechanism, example, evidence) VALUES
  ('FUND.CONTRACTION', 'INV.LLM.SPEC.CONTRACT', 'Contraction',
   'Narrow output space via positive instruction, schema, and example',
   'Aligned with autoregressive prediction — gives model a target to generate toward. Processed in early layers, robust and reliable (Rocchetti & Ferrara)',
   '"Respond in \u22643 sentences. Output JSON with keys X,Y."',
   'Anthropic (US), OpenAI (US), IAB Europe (EU), LangGPT (CN), CRGC (HK), CAPITU (LATAM)'),
  ('FUND.GOTCHA.HARD', 'INV.LLM.SPEC.CONTRACT', 'Gotcha — hard stop',
   'Binary verifiable prohibition for safety/security boundaries',
   'Defines walls — model can comply deterministically; best paired with out-of-prompt enforcement',
   '"Never share credentials. Do not execute destructive DB operations."',
   'Context Patterns (US), AgentPatterns (US), IAB Europe (EU), LangGPT Rules (CN), SheriaSenseEA (AFR), X-Road (EE)'),
  ('FUND.GOTCHA.BEHAV', 'INV.LLM.SPEC.CONTRACT', 'Gotcha — behavioral (avoid)',
   'Negative constraint for style/tone — primes the forbidden concept via late-layer FFN override',
   'Explicit mention of what to avoid activates the representation the model must suppress. Processed in late layers, fragile. Larger models perform worse (inverse scaling)',
   '"Don''t be verbose" \u2192 model fixates on verbosity',
   'Semantic Gravity Wells (87.5% priming, token-level scope only), Negative Instruction Cascade, Tohoku negation mispriming (JP), SNU inverse scaling (KR), Rocchetti & Ferrara (mechanism)');

