INSERT INTO meta_analyses (id, investigation_id, title, key_finding, methodology, sample_description) VALUES
  ('MA.SEMGRAV', 'INV.LLM.SPEC.CONTRACT', 'Semantic Gravity Wells (arXiv 2601.08070)',
   'Negative constraint failure follows logistic curve p = \u03c3(-2.40 + 2.27\u00b7P\u2080); 87.5% priming failure',
   'Mechanistic: logit lens, activation patching', 'n=40,000 samples'),
  ('MA.NEGINST', 'INV.LLM.SPEC.CONTRACT', 'Negative Instruction Cascade (Zenodo 2025)',
   'Threshold at ~40% negatives \u2192 breakdown; 3:1 positive:negative ratio required',
   'Empirical instruction refinement', '3 versions'),
  ('MA.SKILLFUL', 'INV.LLM.SPEC.CONTRACT', 'How LLMs Follow Instructions: Skillful Coordination (Rocchetti & Ferrara 2026)',
   'No universal constraint mechanism; structural constraints in early layers, semantic in late; dynamic monitoring during generation',
   'Diagnostic probing + causal ablation across 9 tasks', '3 models, 9 tasks'),
  ('MA.CRGC', 'INV.LLM.SPEC.CONTRACT', 'CRGC (CUHK 2026)',
   'Bridge constraints reconcile conflicting requirements; reduces violations by 39%',
   'Knowledge graph + automated bridge discovery', '3 IF datasets'),
  ('MA.CONINSTRUCT', 'INV.LLM.SPEC.CONTRACT', 'ConInstruct (HKU, AAAI 2026)',
   '6 constraint types, 9 conflict types; DeepSeek-R1 91.5% F1; models detect but rarely communicate',
   'Benchmark + LLM evaluation', 'Multiple LLMs'),
  ('MA.CSE', 'INV.LLM.SPEC.CONTRACT', 'CSE (Vasileva 2026)',
   'Two-regime decay: 58% at k=1 \u2192 ~16% floor; independent failures; 5-6 constraint ceiling',
   'Deterministic verification across text + vision', '14 text models, 10 VLMs'),
  ('MA.IFSCALE', 'INV.LLM.SPEC.CONTRACT', 'IFScale Follow-up (Arize AI 2026)',
   'Models 10x better at IF in one year; GPT-5.5 99% through 5,000 constraints',
   'Keyword inclusion proxy', 'GPT-4.1 through GPT-5.5, Claude, Gemini'),
  ('MA.SPECGAME.RL', 'INV.LLM.SPEC.CONTRACT', 'Specification Gaming in Reasoning Models (arXiv 2605.02269)',
   'RL reasoning training increases gaming 32-170%; mitigations reduce but don''t eliminate',
   'Multi-environment evaluation', '8 settings, Grok/Claude/GPT/DeepSeek');

